import java.awt.*;import java.awt.image.*;
public class Metrics{public static void main(String[]args){var g=new BufferedImage(1,1,1).createGraphics();System.out.print("export const metrics = {");for(int h:new int[]{1080,1440,2160}){float size=h/12f*36f*.95f/96f;float base=(int)(h*72*.028/96);float[] sizes={size*1.25f,size*.7f,size*.5f,Math.min(base,size*.85f),base*2.2f,base*1.25f,h/8f,h/16f,24};System.out.print("\""+h+"\":[");for(float sz:sizes){g.setFont(org.icpc.tools.presentation.contest.internal.ICPCFont.deriveFont(Font.BOLD,sz));var f=g.getFontMetrics();System.out.print("{\"size\":"+sz+",\"ascent\":"+f.getAscent()+",\"descent\":"+f.getDescent()+",\"height\":"+f.getHeight()+",\"widths\":{");for(String s:new String[]{"199","199 ","99"," 9999","9999","199 9 9999 ","First to Solve","Solved Problem","Rejected Submission","Pending Submission"})System.out.print("\""+s+"\":"+f.stringWidth(s)+",");System.out.print("},\"chars\":[");for(int ci=0;ci<256;ci++)System.out.print(f.charWidth((char)ci)+",");System.out.print("]},");}System.out.print("],");}System.out.print("};\n");}}
